// ── ENCHANTED FOREST — magical woodland, fairy lights, creatures ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime

// Sky gradient (deep twilight feel even during day)
svg += `<defs>
  <linearGradient id="lg-forest" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0A0520' : sc.sky1}"/>
    <stop offset="40%" stop-color="${isN ? '#1A0E35' : '#3A5A6A'}"/>
    <stop offset="100%" stop-color="${isN ? '#0E1A0E' : sc.sky2}"/>
  </linearGradient>
  <radialGradient id="rg-fairy">
    <stop offset="0%" stop-color="rgba(255,215,0,0.4)"/>
    <stop offset="100%" stop-color="rgba(255,215,0,0)"/>
  </radialGradient>
  <linearGradient id="lg-stream" x1="0" y1="0" x2="1" y2="0">
    <stop offset="0%" stop-color="rgba(100,180,220,0.5)"/>
    <stop offset="50%" stop-color="rgba(140,200,240,0.6)"/>
    <stop offset="100%" stop-color="rgba(100,180,220,0.5)"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-forest)"/>`;

// Optional static background image layer (responsive: cover/contain)
const bgAssetRaw = sc && (sc.bgImage || sc.staticBg || sc.backgroundImage || sc.bgAsset) ? String(sc.bgImage || sc.staticBg || sc.backgroundImage || sc.bgAsset).trim() : '';
if (bgAssetRaw) {
  const bgNativeW = Number(sc.bgNativeW || 1920);
  const bgNativeH = Number(sc.bgNativeH || 1080);
  const bgFit = String(sc.bgFit || 'cover').toLowerCase() === 'contain' ? 'contain' : 'cover';
  const scale = bgFit === 'contain'
    ? Math.min(w / Math.max(1, bgNativeW), h / Math.max(1, bgNativeH))
    : Math.max(w / Math.max(1, bgNativeW), h / Math.max(1, bgNativeH));
  const drawW = Math.max(1, bgNativeW * scale);
  const drawH = Math.max(1, bgNativeH * scale);
  const drawX = (w - drawW) * 0.5;
  const drawY = (h - drawH) * 0.5;
  const bgOpacityRaw = Number(sc.bgOpacity);
  const bgOpacity = Number.isFinite(bgOpacityRaw) ? Math.max(0, Math.min(1, bgOpacityRaw)) : 0.28;
  const safeBgAsset = bgAssetRaw
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '')
    .replace(/>/g, '');
  svg += `<image href="${safeBgAsset}" x="${drawX}" y="${drawY}" width="${drawW}" height="${drawH}" preserveAspectRatio="none" opacity="${bgOpacity}"/>`;
}


// ── Forest canopy (top layer — dense leaves filtering light) ──
for (let i = 0; i < 12; i++) {
  const cx2 = w * (-0.05 + i * 0.1);
  const cy2 = h * 0.03 + Math.sin(i * 1.7) * h * 0.03;
  const cr = 35 + Math.sin(i * 2.3) * 12;
  const sway3 = Math.sin(mt * 0.4 + i * 0.8) * 3;
  svg += `<circle cx="${cx2+sway3}" cy="${cy2}" r="${cr}" fill="${isN ? '#0A1A0A' : '#1A4A1A'}" opacity="0.6"/>`;
}

// ── Sunbeams / moonbeams filtering through canopy ──
for (let i = 0; i < 5; i++) {
  const bx2 = w * (0.1 + i * 0.2) + Math.sin(mt * 0.3 + i * 1.5) * 10;
  const beamOp = 0.04 + Math.sin(mt * 0.5 + i * 0.7) * 0.02;
  const beamColor = isN ? 'rgba(180,200,255,' : 'rgba(255,240,180,';
  svg += `<polygon points="${bx2-3},0 ${bx2+3},0 ${bx2+25},${h*0.7} ${bx2-15},${h*0.7}" fill="${beamColor}${beamOp})" />`;
}

// ── Forest floor ──
svg += `<path d="M0 ${bY-15} Q${w*0.1} ${bY-25} ${w*0.2} ${bY-10} Q${w*0.35} ${bY-20} ${w*0.5} ${bY-12} Q${w*0.65} ${bY-22} ${w*0.8} ${bY-8} Q${w*0.9} ${bY-18} ${w} ${bY-10} L${w} ${h} L0 ${h} Z" fill="${sc.ground}" stroke="#1A3A1A" stroke-width="${ol*0.5}"/>`;
// Moss and leaf litter
for (let i = 0; i < 20; i++) {
  const mx = w * (i / 20);
  const my = bY - 5 + Math.sin(i * 1.9) * 8;
  svg += `<ellipse cx="${mx}" cy="${my}" rx="${8+Math.sin(i*1.3)*3}" ry="3" fill="#3A6A3A" opacity="0.3"/>`;
}

// ── BIG TREES (3 ancient oaks) ──
const treePositions = [[w*0.08, 90], [w*0.45, 110], [w*0.82, 85]];
for (let t = 0; t < 3; t++) {
  const ttx = treePositions[t][0];
  const tth = treePositions[t][1];
  const tsway = Math.sin(mt * 0.35 + t * 1.2) * 3;
  // Trunk (thick, gnarled)
  svg += `<path d="M${ttx-8} ${bY-5} Q${ttx-5+tsway*0.3} ${bY-tth*0.5} ${ttx+tsway} ${bY-tth}" fill="none" stroke="#4A3020" stroke-width="${12+t*2}" stroke-linecap="round"/>`;
  // Roots
  for (let r = 0; r < 3; r++) {
    const rdir = r - 1;
    svg += `<path d="M${ttx+rdir*5} ${bY-5} Q${ttx+rdir*18} ${bY+2} ${ttx+rdir*22} ${bY+5}" fill="none" stroke="#3A2818" stroke-width="3" stroke-linecap="round" opacity="0.6"/>`;
  }
  // Canopy (multiple leaf clusters)
  for (let c = 0; c < 6; c++) {
    const lcx = ttx + Math.sin(c * 1.1 + t) * 30 + tsway;
    const lcy = bY - tth - 5 + Math.cos(c * 0.9 + t) * 18;
    const lcr = 18 + Math.sin(c * 2.3 + t * 0.7) * 8;
    svg += `<circle cx="${lcx}" cy="${lcy}" r="${lcr}" fill="${isN ? '#0E2A0E' : '#2A5A2A'}" stroke="${isN ? '#0A1A0A' : '#1A4A1A'}" stroke-width="${ol*0.3}" opacity="0.8"/>`;
  }
  // Tree hollow (owl home on middle tree)
  if (t === 1) {
    const hollowY = bY - tth * 0.45;
    svg += `<ellipse cx="${ttx+3}" cy="${hollowY}" rx="6" ry="8" fill="#1A0E08" stroke="#3A2818" stroke-width="${ol*0.4}"/>`;
  }
}

// ── OWL (sitting in middle tree) ──
const owlX = treePositions[1][0] + 3;
const owlY = bY - treePositions[1][1] * 0.45 - 12;
const owlBlink = Math.sin(mt * 0.8) > 0.95 ? 0 : 1; // occasional blink
// Body
svg += `<ellipse cx="${owlX}" cy="${owlY}" rx="7" ry="9" fill="#8B6B4A" stroke="#6B4B2A" stroke-width="${ol*0.4}"/>`;
// Head
svg += `<circle cx="${owlX}" cy="${owlY-10}" r="6.5" fill="#9B7B5A" stroke="#6B4B2A" stroke-width="${ol*0.4}"/>`;
// Ear tufts
svg += `<polygon points="${owlX-5},${owlY-15} ${owlX-3},${owlY-21} ${owlX-1},${owlY-15}" fill="#7B5B3A"/>`;
svg += `<polygon points="${owlX+1},${owlY-15} ${owlX+3},${owlY-21} ${owlX+5},${owlY-15}" fill="#7B5B3A"/>`;
// Eyes (big round owl eyes!)
if (owlBlink) {
  svg += `<circle cx="${owlX-3}" cy="${owlY-11}" r="3" fill="#FFD700" stroke="#DAA520" stroke-width="0.5"/>`;
  svg += `<circle cx="${owlX+3}" cy="${owlY-11}" r="3" fill="#FFD700" stroke="#DAA520" stroke-width="0.5"/>`;
  svg += `<circle cx="${owlX-3}" cy="${owlY-11}" r="1.5" fill="#222"/>`;
  svg += `<circle cx="${owlX+3}" cy="${owlY-11}" r="1.5" fill="#222"/>`;
} else {
  svg += `<line x1="${owlX-5}" y1="${owlY-11}" x2="${owlX-1}" y2="${owlY-11}" stroke="#222" stroke-width="1.5" stroke-linecap="round"/>`;
  svg += `<line x1="${owlX+1}" y1="${owlY-11}" x2="${owlX+5}" y2="${owlY-11}" stroke="#222" stroke-width="1.5" stroke-linecap="round"/>`;
}
// Beak
svg += `<polygon points="${owlX},${owlY-9} ${owlX-1.5},${owlY-7} ${owlX+1.5},${owlY-7}" fill="#DAA520"/>`;

// ── DEER (right side, grazing) ──
const dx = w * 0.68;
const dy = bY - 8;
const dBob = Math.sin(mt * 0.6) * 2;
// Body
svg += `<ellipse cx="${dx}" cy="${dy+dBob}" rx="18" ry="12" fill="#C4862D" stroke="#A06820" stroke-width="${ol*0.4}"/>`;
// Neck
svg += `<path d="M${dx+10} ${dy-5+dBob} Q${dx+16} ${dy-18+dBob} ${dx+14} ${dy-28+dBob}" fill="none" stroke="#C4862D" stroke-width="8" stroke-linecap="round"/>`;
// Head
svg += `<circle cx="${dx+14}" cy="${dy-32+dBob}" r="6" fill="#D4964A" stroke="#A06820" stroke-width="${ol*0.3}"/>`;
// Ears
svg += `<ellipse cx="${dx+10}" cy="${dy-36+dBob}" rx="3" ry="5" fill="#C4862D" stroke="#A06820" stroke-width="0.5" transform="rotate(-20 ${dx+10} ${dy-36+dBob})"/>`;
svg += `<ellipse cx="${dx+18}" cy="${dy-36+dBob}" rx="3" ry="5" fill="#C4862D" stroke="#A06820" stroke-width="0.5" transform="rotate(20 ${dx+18} ${dy-36+dBob})"/>`;
// Antlers
svg += `<path d="M${dx+11} ${dy-38+dBob} Q${dx+6} ${dy-48} ${dx+3} ${dy-52}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<path d="M${dx+8} ${dy-45+dBob} Q${dx+5} ${dy-50} ${dx+7} ${dy-55}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<path d="M${dx+17} ${dy-38+dBob} Q${dx+22} ${dy-48} ${dx+25} ${dy-52}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
svg += `<path d="M${dx+20} ${dy-45+dBob} Q${dx+23} ${dy-50} ${dx+21} ${dy-55}" fill="none" stroke="#8B6B4A" stroke-width="1.5" stroke-linecap="round"/>`;
// Eye
svg += `<circle cx="${dx+16}" cy="${dy-33+dBob}" r="1.5" fill="#222"/>`;
// Nose
svg += `<ellipse cx="${dx+18}" cy="${dy-30+dBob}" rx="2" ry="1.5" fill="#3A2818"/>`;
// Legs
for (let i = 0; i < 4; i++) {
  const lx2 = dx - 10 + i * 7;
  svg += `<line x1="${lx2}" y1="${dy+10+dBob}" x2="${lx2}" y2="${dy+22}" stroke="#A06820" stroke-width="2.5" stroke-linecap="round"/>`;
}
// White spots on body
for (let i = 0; i < 5; i++) {
  const spx = dx - 10 + i * 5 + Math.sin(i * 3.1) * 3;
  const spy = dy - 3 + Math.cos(i * 2.7) * 4 + dBob;
  svg += `<circle cx="${spx}" cy="${spy}" r="1.5" fill="#FFF" opacity="0.25"/>`;
}
// Baby deer (fawn) next to parent
const fdx = dx - 22;
const fdy = dy + 5;
svg += `<ellipse cx="${fdx}" cy="${fdy+dBob}" rx="10" ry="7" fill="#D4A050" stroke="#A07830" stroke-width="${ol*0.3}"/>`;
svg += `<circle cx="${fdx+6}" cy="${fdy-8+dBob}" r="4.5" fill="#D4A050" stroke="#A07830" stroke-width="${ol*0.3}"/>`;
svg += `<circle cx="${fdx+8}" cy="${fdy-9+dBob}" r="1" fill="#222"/>`;
for (let i = 0; i < 4; i++) svg += `<line x1="${fdx-5+i*4}" y1="${fdy+6+dBob}" x2="${fdx-5+i*4}" y2="${fdy+14}" stroke="#A07830" stroke-width="2" stroke-linecap="round"/>`;

// ── GLOWING MUSHROOMS ──
const mushPositions = [[w*0.15,bY+5],[w*0.28,bY+10],[w*0.38,bY+2],[w*0.58,bY+8],[w*0.72,bY+12],[w*0.92,bY+6]];
const mushColors = ['#FF6B9D','#00CED1','#9370DB','#FF8C42','#4ECDC4','#DA70D6'];
for (let i = 0; i < 6; i++) {
  const mxp = mushPositions[i][0];
  const myp = mushPositions[i][1];
  const mh = 8 + Math.sin(i * 2.1) * 3;
  const glowPulse = Math.sin(mt * 1.5 + i * 1.1) * 0.5 + 0.5;
  // Stem
  svg += `<rect x="${mxp-2}" y="${myp-mh}" width="4" height="${mh}" rx="1" fill="#E8D8C0" stroke="#C8B8A0" stroke-width="${ol*0.2}"/>`;
  // Cap
  svg += `<ellipse cx="${mxp}" cy="${myp-mh}" rx="${7+Math.sin(i*1.7)*2}" ry="${4+Math.sin(i*1.3)}" fill="${mushColors[i]}" stroke="${mushColors[i]}" stroke-width="${ol*0.3}"/>`;
  // Spots on cap
  svg += `<circle cx="${mxp-2}" cy="${myp-mh-1}" r="1" fill="#FFF" opacity="0.5"/>`;
  svg += `<circle cx="${mxp+3}" cy="${myp-mh+1}" r="0.8" fill="#FFF" opacity="0.4"/>`;
  // Glow
  svg += `<circle cx="${mxp}" cy="${myp-mh}" r="${12+glowPulse*6}" fill="${mushColors[i]}" opacity="${0.03+glowPulse*0.04}"/>`;
}

// ── Enchanted stream ──
const streamY2 = bY + 25;
for (let i = 0; i < 3; i++) {
  const sy2 = streamY2 + i * 4;
  const sWave = Math.sin(mt * 1.2 + i * 0.8) * 8;
  svg += `<path d="M0 ${sy2} Q${w*0.15+sWave} ${sy2-4} ${w*0.3} ${sy2+2} Q${w*0.45-sWave} ${sy2-3} ${w*0.6} ${sy2+1} Q${w*0.75+sWave} ${sy2-4} ${w*0.9} ${sy2+2} T${w} ${sy2}" fill="none" stroke="rgba(120,190,230,${0.2+Math.sin(mt*0.8+i)*0.1})" stroke-width="${3-i*0.5}"/>`;
}
// Stream sparkles
for (let i = 0; i < 8; i++) {
  const skx = w * (0.05 + i * 0.12) + Math.sin(mt * 0.5 + i * 1.3) * 5;
  const sky = streamY2 + Math.sin(i * 2.1) * 3;
  const skop = 0.3 + Math.sin(mt * 2 + i * 0.9) * 0.3;
  svg += `<circle cx="${skx}" cy="${sky}" r="1" fill="#FFF" opacity="${skop}"/>`;
}

// ── Fireflies / fairy lights ──
for (let i = 0; i < 18; i++) {
  const ffx = (Math.sin(i * 47.3 + 3.1) * 0.5 + 0.5) * w;
  const ffy = bY - 40 + (Math.sin(i * 83.7 + 7.3) * 0.5 + 0.5) * 60;
  const ffDrift = Math.sin(mt * 0.7 + i * 0.97) * 12;
  const ffUp = Math.cos(mt * 0.5 + i * 1.3) * 8;
  const ffop = 0.2 + Math.sin(mt * 2 + i * 1.1) * 0.3;
  const ffr = 1.5 + Math.sin(mt * 1.5 + i * 0.8) * 0.8;
  svg += `<circle cx="${ffx+ffDrift}" cy="${ffy+ffUp}" r="${ffr}" fill="${sc.acc}" opacity="${ffop}"/>`;
  svg += `<circle cx="${ffx+ffDrift}" cy="${ffy+ffUp}" r="${ffr*3}" fill="${sc.acc}" opacity="${ffop*0.1}"/>`;
}

// ── Flowers on forest floor ──
for (let i = 0; i < 10; i++) {
  const flx = w * (0.03 + i * 0.1);
  const fly = bY - 2 + Math.sin(i * 1.8) * 5;
  const flSway = Math.sin(mt * 0.9 + i * 0.7) * 2;
  const flColors = ['#FF69B4','#DDA0DD','#87CEEB','#98FB98','#FFB6C1','#E6E6FA','#FFA07A','#20B2AA','#F0E68C','#DB7093'];
  svg += `<line x1="${flx}" y1="${fly}" x2="${flx+flSway}" y2="${fly-8}" stroke="#2A5A2A" stroke-width="1" stroke-linecap="round"/>`;
  svg += `<circle cx="${flx+flSway}" cy="${fly-9}" r="2.5" fill="${flColors[i]}" opacity="0.8"/>`;
}

// ── Butterflies (2 animated) ──
for (let i = 0; i < 2; i++) {
  const btx = w * (0.3 + i * 0.35) + Math.sin(mt * 0.6 + i * 2.1) * 40;
  const bty = bY - 30 - i * 20 + Math.cos(mt * 0.5 + i * 1.7) * 15;
  const wingFlap = Math.sin(mt * 6 + i * 3) * 6;
  const btCol = i === 0 ? '#FF69B4' : '#87CEEB';
  // Wings
  svg += `<ellipse cx="${btx-3}" cy="${bty}" rx="${3+wingFlap*0.3}" ry="4" fill="${btCol}" opacity="0.7" transform="rotate(${-wingFlap*2} ${btx-3} ${bty})"/>`;
  svg += `<ellipse cx="${btx+3}" cy="${bty}" rx="${3+wingFlap*0.3}" ry="4" fill="${btCol}" opacity="0.7" transform="rotate(${wingFlap*2} ${btx+3} ${bty})"/>`;
  // Body
  svg += `<ellipse cx="${btx}" cy="${bty}" rx="1" ry="3" fill="#333"/>`;
}

// ── Moon / Sun ──
if (!isN) {
  // Dappled sunlight through canopy
  svg += `<circle cx="${w*0.5}" cy="${h*0.08}" r="${30+w1*8}" fill="#FFF8E0" opacity="0.08"/>`;
} else {
  svg += `<circle cx="${w*0.5}" cy="${h*0.07}" r="14" fill="#EDE8DF" opacity="0.75"/>`;
  svg += `<circle cx="${w*0.5+4}" cy="${h*0.07-3}" r="11" fill="#0A0520" opacity="0.9"/>`;
  // Moonbeam through trees
  svg += `<polygon points="${w*0.48},${h*0.12} ${w*0.52},${h*0.12} ${w*0.56},${h*0.6} ${w*0.44},${h*0.6}" fill="rgba(200,210,230,0.03)"/>`;
}
